        @if (selectedChannel is not null)
        {
            <div class="main-header">
                <h2># @selectedChannel.Name</h2>
                <span class="main-header-desc">@selectedChannel.Description</span>
            </div>

            <div class="message-list" @onscroll="HandleScroll" @ref="messageListRef">
