                                   ReplyCount="GetReplyCount(msg.Id)"
                                   OnOpenThread="HandleOpenThread"
                                   OnReact="HandleReact" />
                }
            </div>

            <MessageInput Placeholder="@($"Message #{selectedChannel.Name}")"
                          ButtonLabel="Send"
                          OnSubmit="HandleSendMessage" />
        }
        else
