@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private Dictionary<int, int> replyCountMap = new();
    private Channel? selectedChannel;
    private int selectedChannelId;

    // Thread state
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    // Pagination
    private const int PageSize = 30;
    private int messageSkip;
    private bool isLoadingMore;
    private bool hasMoreMessages = true;
    private ElementReference messageListRef;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();

        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task HandleChannelSelected(int channelId)
    {
        if (channelId == selectedChannelId) return;
        threadRootMessage = null;
        threadReplies = [];
        await SelectChannel(channelId);
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messageSkip = 0;
        hasMoreMessages = true;
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        messageSkip = messages.Count;

        await ChatService.MarkChannelReadAsync(channelId);
        await BuildReplyCountMap();
    }

    private async Task BuildReplyCountMap()
    {
        replyCountMap.Clear();
        // Identify thread root messages (messages that have replies pointing to them)
        var rootIds = messages
            .Where(m => m.ReplyToId is null)
            .Select(m => m.Id)
            .ToHashSet();

        foreach (var rootId in rootIds)
        {
            var thread = await ChatService.GetThreadAsync(rootId);
            if (thread.Count > 0)
            {
                replyCountMap[rootId] = thread.Count;
            }
        }
    }

    private int GetReplyCount(int messageId) =>
        replyCountMap.TryGetValue(messageId, out var count) ? count : 0;

    private async Task HandleScroll()
    {
        // Scroll-to-top pagination is handled via JS interop in production;
        // here we provide the mechanism via the scroll event.
        // A real implementation would check scrollTop === 0 via JS interop.
        // For now, expose a load-more that can be triggered.
    }

    public async Task LoadOlderMessages()
    {
        if (isLoadingMore || !hasMoreMessages || selectedChannel is null) return;

        isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(selectedChannelId, messageSkip, PageSize);
        if (older.Count < PageSize) hasMoreMessages = false;

        messages.InsertRange(0, older);
        messageSkip += older.Count;
        isLoadingMore = false;
    }

    private async Task HandleSendMessage(string content)
    {
        if (selectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(msg);
    }

