    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadReplies = await ChatService.GetThreadAsync(messageId);
    }

    private void HandleCloseThread()
    {
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task HandleSendThreadReply(string content)
    {
        if (threadRootMessage is null || selectedChannel is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update reply count
        replyCountMap[threadRootMessage.Id] = threadReplies.Count;
    }

    private async Task HandleReact((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistically update UI — find the message and add/update the reaction
        var target = messages.FirstOrDefault(m => m.Id == args.MessageId)
                     ?? threadReplies.FirstOrDefault(m => m.Id == args.MessageId);
        if (target is not null)
        {
            var existing = target.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
            if (existing is not null)
            {
                if (!existing.Users.Contains("You"))
                    existing.Users.Add("You");
            }
            else
            {
                target.Reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
        }
    }
