{"file_text": ".chat-container {
    display: flex;
    height: 100%;
    width: 100%;
    overflow: hidden;
}

/* Left sidebar — ~20% */
.panel-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

/* Main message area — fills remaining space */
.panel-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    background: #fff;
    overflow: hidden;
}

/* When thread is open, main area shrinks */
.panel-main.with-thread {
    flex: 0 0 55%;
}

/* Thread panel — ~25% */
.panel-thread {
    width: 25%;
    min-width: 280px;
    flex-shrink: 0;
}

/* Main header */
.main-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
    background: #fff;
}

.main-header h2 {
    margin: 0;
    font-size: 1.15rem;
    font-weight: 700;
    color: #1a1a1a;
}

.main-header-desc {
    font-size: 0.82rem;
    color: #777;
}

/* Scrollable message list */
.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #999;
    font-size: 0.85rem;
}

.no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 1.1rem;
}
