+            </div>
+
+            <MessageInput Placeholder="@($"Message #{selectedChannel.Name}")"
+                          ButtonLabel="Send"
+                          OnSubmit="HandleSendMessage" />
+        }
+        else
+        {
+            <div class="no-channel-selected">
+                <p>Select a channel to start chatting</p>
+            </div>
+        }
+    </div>
+
+    @* Right panel — thread view *@
+    @if (threadRootMessage is not null)
+    {
+        <div class="panel-thread">
+            <ThreadPanel RootMessage="threadRootMessage"
+                         Replies="threadReplies"
+                         OnClose="HandleCloseThread"
+                         OnReply="HandleSendThreadReply"
+                         OnReact="HandleReact" />
+        </div>
+    }
+</div>
+
+@code {
+    private List<Channel> channels = [];
+    private List<Message> messages = [];
+    private Dictionary<int, int> replyCountMap = new();
+    private Channel? selectedChannel;
+    private int selectedChannelId;
+
+    // Thread state
+    private Message? threadRootMessage;
+    private List<Message> threadReplies = [];
+
+    // Pagination
+    private const int PageSize = 30;
+    private int messageSkip;
+    private bool isLoadingMore;
+    private bool hasMoreMessages = true;
+    private ElementReference messageListRef;
+
+    protected override async Task OnInitializedAsync()
+    {
+        channels = await ChatService.GetChannelsAsync();
+
+        if (channels.Count > 0)
+        {
+            await SelectChannel(channels[0].Id);
+        }
+    }
+
+    private async Task HandleChannelSelected(int channelId)
+    {
+        if (channelId == selectedChannelId) return;
+        threadRootMessage = null;
+        threadReplies = [];
+        await SelectChannel(channelId);
+    }
+
+    private async Task SelectChannel(int channelId)
+    {
+        selectedChannelId = channelId;
+        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
+        messageSkip = 0;
+        hasMoreMessages = true;
+        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
+        messageSkip = messages.Count;
+
+        await ChatService.MarkChannelReadAsync(channelId);
+        await BuildReplyCountMap();
+    }
+
+    private async Task BuildReplyCountMap()
+    {
+        replyCountMap.Clear();
+        // Identify thread root messages (messages that have replies pointing to them)
+        var rootIds = messages
+            .Where(m => m.ReplyToId is null)
+            .Select(m => m.Id)
+            .ToHashSet();
+
+        foreach (var rootId in rootIds)
+        {
+            var thread = await ChatService.GetThreadAsync(rootId);
+            if (thread.Count > 0)
+            {
+                replyCountMap[rootId] = thread.Count;
+            }
+        }
+    }
+
+    private int GetReplyCount(int messageId) =>
+        replyCountMap.TryGetValue(messageId, out var count) ? count : 0;
+
+    private async Task HandleScroll()
+    {
+        // Scroll-to-top pagination is handled via JS interop in production;
+        // here we provide the mechanism via the scroll event.
+        // A real implementation would check scrollTop === 0 via JS interop.
+        // For now, expose a load-more that can be triggered.
+    }
+
+    public async Task LoadOlderMessages()
+    {
+        if (isLoadingMore || !hasMoreMessages || selectedChannel is null) return;
+
+        isLoadingMore = true;
+        StateHasChanged();
+
+        var older = await ChatService.GetMessagesAsync(selectedChannelId, messageSkip, PageSize);
+        if (older.Count < PageSize) hasMoreMessages = false;
+
+        messages.InsertRange(0, older);
+        messageSkip += older.Count;
+        isLoadingMore = false;
+    }
+
+    private async Task HandleSendMessage(string content)
+    {
+        if (selectedChannel is null) return;
+        var msg = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
+        messages.Add(msg);
+    }
+
+    private async Task HandleOpenThread(int messageId)
+    {
+        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
+        if (threadRootMessage is null) return;
+
+        threadReplies = await ChatService.GetThreadAsync(messageId);
+    }
+
+    private void HandleCloseThread()
+    {
+        threadRootMessage = null;
+        threadReplies = [];
+    }
+
+    private async Task HandleSendThreadReply(string content)
+    {
+        if (threadRootMessage is null || selectedChannel is null) return;
+        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
+        threadReplies.Add(reply);
+
+        // Update reply count
+        replyCountMap[threadRootMessage.Id] = threadReplies.Count;
+    }
+
+    private async Task HandleReact((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+
+        // Optimistically update UI — find the message and add/update the reaction
+        var target = messages.FirstOrDefault(m => m.Id == args.MessageId)
+                     ?? threadReplies.FirstOrDefault(m => m.Id == args.MessageId);
+        if (target is not null)
+        {
+            var existing = target.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
+            if (existing is not null)
+            {
+                if (!existing.Users.Contains("You"))
+                    existing.Users.Add("You");
+            }
+            else
+            {
+                target.Reactions.Add(new Reaction(args.Emoji, ["You"]));
+            }
+        }
+    }
+}
+

toolArgs.file_text:
.chat-container {
    display: flex;
    height: 100%;
    width: 100%;
    overflow: hidden;
}

/* Left sidebar — ~20% */
.panel-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

/* Main message area — fills remaining space */
.panel-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    background: #fff;
    overflow: hidden;
}

/* When thread is open, main area shrinks */
.panel-main.with-thread {
    flex: 0 0 55%;
}

/* Thread panel — ~25% */
.panel-thread {
    width: 25%;
    min-width: 280px;
    flex-shrink: 0;
}

/* Main header */
.main-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
    background: #fff;
}

.main-header h2 {
    margin: 0;
    font-size: 1.15rem;
    font-weight: 700;
    color: #1a1a1a;
}

.main-header-desc {
    font-size: 0.82rem;
    color: #777;
}

/* Scrollable message list */
.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #999;
    font-size: 0.85rem;
}

.no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 1.1rem;
}

